CREATE OR REPLACE VIEW `v_events` AS SELECT `e`.`id` AS `id`, `e`.`kind` AS `kind`, `e`.`title` AS `title`, `e`.`subject_id` AS `subject_id`, `s`.`code` AS `subject_code`, `s`.`name` AS `subject_name`, `e`.`class_id` AS `class_id`, `e`.`group_id` AS `group_id`, `e`.`starts_at` AS `starts_at`, `e`.`ends_at` AS `ends_at`, `e`.`all_day` AS `all_day`, `e`.`place` AS `place`, `e`.`note` AS `note`, `e`.`topic_id` AS `topic_id`, `e`.`created_by` AS `created_by`, `e`.`created_at` AS `created_at` FROM `events` `e` LEFT JOIN `subjects` `s` ON `s`.`id` = `e`.`subject_id` WHERE `e`.`deleted_at` IS NULL;
